Supervisor: import { EventEmitter } from 'events';

export enum AgentRole {
    JULES = 'JULES',
    SENTINEL = 'SENTINEL',
    SUPERVISOR = 'SUPERVISOR'
}

export enum TaskStatus {
    PENDING = 'PENDING',
    IN_PROGRESS = 'IN_PROGRESS',
    COMPLETED = 'COMPLETED',
    FAILED = 'FAILED'
}

export interface Task {
    id: string;
    type: 'UI_DEVELOPMENT' | 'SECURITY_CHECK' | 'STATE_SYNC' | 'VALIDATION';
    priority: number;
    payload: any;
    status: TaskStatus;
    assignedTo?: AgentRole;
    result?: any;
}

export interface GlobalState {
    lastSync: number;
    activeTasks: Task[];
    context: Record<string, any>;
}

export class SupervisorAgent extends EventEmitter {
    private state: GlobalState;
    private agents: Map<AgentRole, any>;

    constructor() {
        super();
        this.state = {
            lastSync: Date.now(),
            activeTasks: [],
            context: {}
        };
        this.agents = new Map();
    }

    public registerAgent(role: AgentRole, instance: any): void {
        this.agents.set(role, instance);
        this.log(`Agent ${role} registered.`);
    }
